<?php require __DIR__.'/includes/bootstrap.php';$type=trim((string)get('type','articles'));$slug=trim((string)get('slug',''));$st=db()->prepare('SELECT p.*,u.name author_name,c.name category_name FROM content_posts p LEFT JOIN users u ON u.id=p.author_id LEFT JOIN categories c ON c.id=p.category_id WHERE p.post_type=? AND p.slug=? AND p.status="publish" LIMIT 1');$st->execute([$type,$slug]);$p=$st->fetch();if(!$p){http_response_code(404);exit('Content not found');}$title=$p['seo_title']?:$p['title'];$meta_description=$p['seo_description']?:$p['excerpt'];$meta_keywords=$p['seo_keywords']?:'';$comments=db()->prepare("SELECT * FROM comments WHERE post_id=? AND status='approved' ORDER BY id DESC");$comments->execute([$p['id']]);$comments=$comments->fetchAll();$tags=db()->prepare('SELECT t.* FROM terms t JOIN post_terms pt ON pt.term_id=t.id WHERE pt.post_id=?');$tags->execute([$p['id']]);$tags=$tags->fetchAll();require __DIR__.'/includes/header.php';$full=$p['content'];$plain=trim(preg_replace('/\s+/',' ',strip_tags($full))??'');$words=preg_split('/\s+/',$plain,-1,PREG_SPLIT_NO_EMPTY);$needMore=count($words)>200;$preview=implode(' ',array_slice($words,0,200));if($needMore)$preview.='…';?>
<article class="max-w-5xl mx-auto px-3 sm:px-5 py-10"><div class="grid lg:grid-cols-[1fr_280px] gap-7"><div><div class="text-xs uppercase tracking-[.2em] text-blue-600 font-black"><?=e(post_type_label($type))?></div><h1 class="text-4xl sm:text-6xl font-black tracking-tight mt-3"><?=e($p['title'])?></h1><div class="mt-4 text-sm text-slate-500"><?=e($p['author_name']??'PAROKO')?> · <?=e($p['published_at']??$p['created_at'])?></div><?php if($p['cover_image']):?><img src="<?=e($p['cover_image'])?>" alt="<?=e($p['title'])?>" class="w-full aspect-[16/9] object-cover rounded-[28px] mt-8 soft"><?php endif;?><div class="bg-white border rounded-[28px] mt-8 overflow-hidden"><div class="flex overflow-x-auto border-b scrollbar-none"><button class="ctab px-5 py-4 border-b-2 border-blue-600 font-black" data-pane="content">Content</button><button class="ctab px-5 py-4 text-slate-500 font-bold" data-pane="comments">Comments (<?=count($comments)?>)</button></div><div class="p-5 sm:p-7"><section data-pane-content="content"><div class="prose prose-slate max-w-none leading-8" id="articleContent"><?php if($needMore):?><p><?=e($preview)?></p><?php else:?><?=render_shortcodes($full)?><?php endif;?></div><?php if($needMore):?><button id="articleMore" class="mt-4 text-blue-600 font-black">Show more <span class="iconify inline" data-icon="solar:alt-arrow-down-linear"></span></button><?php endif;?></section><section data-pane-content="comments" class="hidden"><form method="post" action="/comment.php" class="grid gap-3"><?=csrf_input()?><input type="hidden" name="post_id" value="<?=$p['id']?>"><input name="author_name" required placeholder="Your name" class="rounded-xl border-slate-200"><input name="author_email" type="email" placeholder="Email" class="rounded-xl border-slate-200"><textarea name="comment" required placeholder="Write a comment" class="rounded-xl border-slate-200 min-h-28"></textarea><button class="shine grad600 text-white rounded-xl py-3 font-black">Submit for moderation</button></form><div class="mt-6 space-y-3"><?php foreach($comments as $c):?><div class="rounded-2xl bg-white border p-4"><div class="font-bold"><?=e($c['author_name']??'Guest')?></div><div class="text-sm text-slate-600 mt-2"><?=nl2br(e($c['comment']))?></div></div><?php endforeach;?></div></section></div></div></div><aside><div class="bg-white border rounded-[24px] p-5 sticky top-28"><div class="font-black">Article details</div><div class="mt-4 space-y-3 text-sm"><div><span class="text-slate-400">Type</span><div class="font-bold mt-1"><?=e(post_type_label($type))?></div></div><div><span class="text-slate-400">Category</span><div class="font-bold mt-1"><?=e($p['category_name']??'Uncategorized')?></div></div><div><span class="text-slate-400">Visibility</span><div class="font-bold mt-1"><?=e($p['visibility'])?></div></div></div><div class="flex flex-wrap gap-2 mt-5"><?php foreach($tags as $t):?><span class="px-3 py-1 rounded-full bg-slate-100 text-xs font-bold">#<?=e($t['name'])?></span><?php endforeach;?></div></div></aside></div></article><script>document.querySelectorAll('.ctab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.ctab').forEach(x=>x.classList.remove('border-blue-600','text-slate-900'));document.querySelectorAll('.ctab').forEach(x=>x.classList.add('text-slate-500'));b.classList.add('border-blue-600','text-slate-900');document.querySelectorAll('[data-pane-content]').forEach(x=>x.classList.add('hidden'));document.querySelector('[data-pane-content="'+b.dataset.pane+'"]').classList.remove('hidden')});<?php if($needMore):?>const fullContent=<?=json_encode(render_shortcodes($full),JSON_UNESCAPED_UNICODE)?>;let expanded=false;document.getElementById('articleMore').onclick=()=>{expanded=!expanded;document.getElementById('articleContent').innerHTML=expanded?fullContent:'<p><?=e($preview)?></p>';document.getElementById('articleMore').innerHTML=expanded?'Show less <span class="iconify inline" data-icon="solar:alt-arrow-up-linear"></span>':'Show more <span class="iconify inline" data-icon="solar:alt-arrow-down-linear"></span>'};<?php endif;?></script><?php require __DIR__.'/includes/footer.php'; ?>
